  intros w Hw Hin; repeat (destruct Hw as [<-|Hw]; [unfold L5.in_rng in Hin; cbn [fst snd] in Hin; lia|]); destruct Hw.
Ltac cc_kt := cbv beta; lazymatch goal with
  | |- _ /\ _ => split; cc_kt
