Lemma m2_kr : forall (R R' : bvmap 5 word) (r : reg), TK.keepsR CK.CSR R R' -> existsb (Nat.eqb (ridx r)) CK.CSR = true -> getr R' r = getr R r.
Proof. intros R R' r H Hb. apply H. apply existsb_exists in Hb. destruct Hb as (q & Hq & Hb). apply Nat.eqb_eq in Hb. subst q. exact Hq. Qed.
