Proof. intros K M M' a v AG H Ha Hc. exact (TK2.u8_x K M M' AG a v Ha Hc H). Qed.
Lemma cc_syscat (LB : list (Z * Z)) (cr : credit) (C IS E sp r kx bx : Z) (rep : PML.srep) (g : PML.ls_state)
  (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K : ShapeAlg.TSet)
  (ch b p : Z) (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model)
  (Hcont : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LB' : list (Z * Z)) (cr' : credit) (LBk : list (Z * Z)) (W : list L5.range), PML.fp_ok fx' -> (exists (ch : Z) (ps' : PML.pstate) (code gp' rdst' : Z) (g' : PML.ls_state) (bof' dn' : bool), PMCS.cursor_at M' C IS ch bof' dn' ps' /\ PML.isrc_at M' IS rep gp' rdst' /\ PMCS.rn_bound ps' IS rep gp' (Z.of_nat (length (PML.srep_chars rep))) /\ PML.ec_at M' E code /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.regJ g) /\ PMCUR.wf_c ps' /\ PML.win_ok M' ((ch, 16384) :: LB) ps' /\ PML.u8 M' 0xd5030 1 /\ LB' = PML.ps_blocks ps' ++ (ch, 16384) :: LB /\ LBk = LB /\ PML.pcredit_x L cr' ps' kx bx /\ W = [(C, PMCS.CURSOR_SIZE); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] /\ (code = 0 -> dn' = false -> PML.ps_more ps' = false /\ ((PML.ps_done ps' = true /\ PML.ps_st ps' = PML.ST_DONE) \/ (PMCUR.wf_c (PMCUR.ps_set_more ps' true) /\ PMCS.evc M' (C + 592) 0 ((ch, 16384) :: LB) ps')))) -> regs_preserved R0 R' -> L5C.hpres L LBk sp (PMCS.CCTOR_SCR STRTOD_SCR) W M0 M' -> model_but_vm model0 model' -> hi_heap HI LB' cr' M' (m_vmmaps model') -> srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model') K)
  (Hmo : PML.model_ok model)
  (BV0 : model_but_vm model0 model)
  (HK0 : K [])
  (Hfp : PML.fp_ok fx)
  (H2 : getr R 2%bv = Z_to_bv 64 (sp - 400))
  (H4 : getr R 4%bv = Z_to_bv 64 PML.TP)
  (H8 : getr R 8%bv = Z_to_bv 64 E)
  (H9 : getr R 9%bv = Z_to_bv 64 C)
  (KOR : TK.keepsR CCS.KO7 R0 R)
  (H2R0 : getr R0 2%bv = Z_to_bv 64 sp)
  (HH : hi_heap HI (PML.ps_blocks (PMS.ps_init b p) ++ (ch, 16384) :: LB) (debit L (debit L (debit L cr 16384) 264) 66) M (m_vmmaps model))
  (CUR : PMCS.cursor_at M C IS ch true false (PMS.ps_init b p))
  (ISRC : PML.isrc_at M IS rep (PML.srep_data (IS + 80) rep) 0)
  (ECL : PML.ec_at M (sp - 384) 0)
  (CHF : forall b0, In b0 (PML.srep_blocks rep) -> In b0 ((ch, 16384) :: LB) /\ fst b0 <> ch)
  (NLEN : Z.of_nat (length (PML.srep_chars rep)) < 2 ^ 26)
  (LSg : PML.ls_ok g M)
  (HG : g <> PML.LS0)
  (PC : PML.pcredit_x L (debit L (debit L (debit L cr 16384) 264) 66) (PMS.ps_init b p) kx bx)
  (STK0 : L5C.stk (hl_sptop L) M0 sp (PMCS.CCTOR_SCR STRTOD_SCR))
  (Hrok : L5.ra_ok r)
  (OC : PML.obj_on_stack L sp C 656)
  (OI : PML.obj_on_stack L sp IS 272)
  (OE : PML.obj_on_stack L sp E 16)
  (APCI : box (C + 656 <= IS \/ IS + 272 <= C))
  (APCE : box (C + 656 <= E \/ E + 16 <= C))
  (APIE : box (IS + 272 <= E \/ E + 16 <= IS))
  (WF : CCS.cells64 M (CCS.wframe sp r R0))
  (CF : CCS.cells64 M (CCS.cframe sp C IS E (bv_unsigned (getr R0 22%bv))))
  (O16 : L5.u64_at RSEGS M (sp - 288) PML.VT_FUNC)
  (O48 : L5.u64_at RSEGS M (sp - 256) (sp - 288))
  (OZ : CCS.zeros M (sp - 224) 144)
  (RO : PML.img_ro M)
  (SG : PML.u8 M 0xd5030 1)
  (EC0 : PML.ec_at M E 0)
  (FR : TK2.FR L LB sp (PMCS.CCTOR_SCR STRTOD_SCR) (fun a => C <= a < C + 656 \/ 0xd5030 <= a < 0xd5032) M0 M)
  (DW : forall a, 0 <= a < 2 ^ 64 -> ~ L5.outside [(C, 656); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] a -> M0 (Z_to_bv 64 a) <> None -> M (Z_to_bv 64 a) <> None)
  (BOK : TK2.blocks_ok L LB)
  (cat : Z) (H10 : getr R 10%bv = Z_to_bv 64 cat) (Hcat : 0 <= cat < 2 ^ 64) (H20 : getr R 20%bv = Z_to_bv 64 (C + 592)) :
  srealizes RSEGS SCFG (@PML.cfg fx R CCT.R_SYSCAT M model) K.
Proof.
  pose proof STK0 as (S1 & S2 & S3 & S4 & S5).
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI.
  assert (HSCR : PMCS.CCTOR_SCR STRTOD_SCR = 400 + PMCS.RN_SCR STRTOD_SCR /\ 9520 <= PMCS.RN_SCR STRTOD_SCR).
  { unfold PMCS.CCTOR_SCR, PMCS.CCTOR_MAIN_SCR, PMCS.RN_SCR, PMS.READNEXT_SCR, PMS.PSOME_SCR, PMS.PF_SCR, PMS.CTOR_SCR, PMS.OPNEW_SCR, PML.HEAP_STACK. lia. }
  destruct HSCR as (HSCR & HRN2).
  assert (SPOK : CK.spok sp) by (split; [lia | exact S1]).
  pose proof OC as (OC1 & OC2 & OC3). pose proof OI as (OI1 & OI2 & OI3). pose proof OE as (OE1 & OE2 & OE3).
  pose proof Hmo as (Hh & Hl & Hmat).
  pose proof ECL as (ECU & ECD & ECC).
  assert (DX : L5.defined M (sp - 376) 8).
  { intros i Hi. replace (sp - 376 + i) with (sp - 384 + (8 + i)) by lia. apply ECD. lia. }
  pose proof (TK2.blocks_ok_heap L HI HIok _ _ M _ HH) as BLK.
  apply (CCS.s_r_syscat FPM fx R M model K sp cat Hh Hl Hfp H2 SPOK H10 Hcat DX).
  intros fx' R' M' Hfp' H2' H1' H10' H11' H12' KR U64 SAM MG.
  assert (H4' : getr R' 4%bv = Z_to_bv 64 PML.TP) by (rewrite (m2_kr R R' (4%bv : reg) KR eq_refl); exact H4).
  assert (H8' : getr R' 8%bv = Z_to_bv 64 E) by (rewrite (m2_kr R R' (8%bv : reg) KR eq_refl); exact H8).
  assert (H9' : getr R' 9%bv = Z_to_bv 64 C) by (rewrite (m2_kr R R' (9%bv : reg) KR eq_refl); exact H9).
  assert (Ha0' : getr R' 10%bv = Z_to_bv 64 C) by (rewrite H10'; exact H9).
  assert (Ha1' : getr R' 11%bv = Z_to_bv 64 (C + 592)) by (rewrite H11'; exact H20).
  assert (KOR' : TK.keepsR CCS.KO7 R0 R') by exact (TK.keepsR_trans _ R0 R R' KOR (CCTL.sub_ko7 CK.CSR R R' KR eq_refl)).
  pose proof (TK2.heap_stack_write L HI HIok LAY _ _ M M' _ (sp - 376) (sp - 368) HH ltac:(lia) ltac:(lia) ltac:(lia) SAM MG) as HH'.
  assert (LOWK : forall a, 0 <= a < hl_ceil L -> a < hl_img_lo L \/ hl_img_hi L <= a -> ~ (sp - 376 <= a < sp - 368)) by (intros a Ha _; lia).
  assert (PSC : TK2.ps_cov (fun a => ~ (sp - 376 <= a < sp - 368)) (PMS.ps_init b p)).
  { apply (CCTL.ps_cov_low L); [intros bb Hb; apply BLK; apply in_or_app; left; exact Hb | lia | exact LOWK]. }
  pose proof (cursor_at_x _ M M' C IS ch true false (PMS.ps_init b p) SAM ltac:(lia) ltac:(intros i Hi; cbv beta; lia) PSC MG CUR) as CUR'.
  assert (STRC : TK2.str_cov (fun a => ~ (sp - 376 <= a < sp - 368)) (IS + 80) rep).
  { apply (CCTL.str_cov_low L); [intros bb Hb; apply BLK; apply in_or_app; right; exact (proj1 (CHF bb Hb)) | lia | exact LOWK | intros i Hi; cbv beta; lia]. }
  pose proof (TK2.isrc_at_x _ M M' SAM IS rep _ 0 ltac:(lia) ltac:(intros i Hi; cbv beta; lia) STRC ISRC) as ISRC'.
  assert (ECL' : PML.ec_at M' (sp - 384) 0).
  { split; [apply (TK2.u32_x _ M M' SAM); [lia | intros i Hi; cbv beta; lia | exact ECU] | split; [intros i Hi; apply MG; apply ECD; exact Hi | left; reflexivity]]. }
  assert (SC : TK2.statics_cov (fun a => ~ (sp - 376 <= a < sp - 368))).
  { split; [|split].
    - intros a (iv & Hiv & Hr). unfold PML.ll_foot_csrc in Hiv. cbn [In] in Hiv.
      repeat destruct Hiv as [<- | Hiv]; try contradiction; cbn [fst snd] in Hr; lia.
    - intros a Ha. unfold PML.IMG_RO_HI in Ha. lia.
    - intros a Ha. lia. }
  pose proof (TK2.ls_ok_x _ M M' SAM SC g LSg) as LSg'.
  pose proof (TK2.img_ro_x _ M M' SAM SC RO) as RO'.
  pose proof (m2_u8 _ M M' _ _ SAM SG ltac:(lia) ltac:(intros i Hi; cbv beta; lia)) as SG'.
  pose proof (TK2.ec_at_x _ M M' SAM E 0 ltac:(lia) ltac:(intros i Hi; cbv beta; lia) EC0) as EC0'.
  pose proof (TK2.u64_x _ M M' SAM (sp - 288) _ ltac:(lia) ltac:(intros i Hi; cbv beta; lia) O16) as O16'.
  pose proof (TK2.u64_x _ M M' SAM (sp - 256) _ ltac:(lia) ltac:(intros i Hi; cbv beta; lia) O48) as O48'.
  pose proof (CCS.zeros_samem _ M M' (sp - 224) 144 SAM ltac:(lia) ltac:(lia) ltac:(intros i Hi; cbv beta; lia) OZ) as OZ'.
  assert (WF' : CCS.cells64 M' (CCS.wframe sp r R0)).
  { apply (CCS.cells64_win _ M M' _ (sp - 56) sp SAM); [lia | lia | intros i Hi; cbv beta; lia | | exact WF].
    intros av Hav. unfold CCS.wframe in Hav. cbn [In] in Hav. repeat destruct Hav as [<- | Hav]; try contradiction; cbn [fst]; lia. }
  assert (CF' : CCS.cells64 M' (CCS.cframe sp C IS E (bv_unsigned (getr R0 22%bv)))).
  { apply (CCS.cells64_win _ M M' _ (sp - 368) (sp - 304) SAM); [lia | lia | intros i Hi; cbv beta; lia | | exact CF].
    intros av Hav. unfold CCS.cframe in Hav. cbn [In] in Hav. repeat destruct Hav as [<- | Hav]; try contradiction; cbn [fst]; lia. }
  pose proof (TK2.FR_samem L LB sp (PMCS.CCTOR_SCR STRTOD_SCR) _ M0 M M' _ FR SAM) as FRx.
  assert (FRc : forall a, 0 <= a < 2 ^ 64 -> client_addr L LB sp (PMCS.CCTOR_SCR STRTOD_SCR) a -> True -> True -> ~ (sp - 376 <= a < sp - 368)).
  { intros a Ha Hcl _ _ Hw. destruct Hcl as [(bb & Hb & Hr) | [(Hc1 & Hc2) | (Hi1 & Hi2)]].
    - destruct (BOK bb Hb) as (_ & _ & _ & _ & Hce). lia.
    - lia.
    - lia. }
  pose proof (FRx (fun a Ha Hcl _ _ => FRc a Ha Hcl I I) (fun a _ Hn => MG _ Hn)) as FR'.
  pose proof (fun a Ha Ho H0 => MG _ (DW a Ha Ho H0)) as DW'.
  apply (CCTL.tail_ok L HI HIok LAY FPM STRTOD_SCR RNEXT SETEC2 LB cr C IS E sp r kx bx rep g R0 M0 model0 K ch b p fx' R' M' model); assumption.
Qed.

Lemma m2_kq : forall (qs : list nat) (R R' : bvmap 5 word) (r : reg), TK.keepsR qs R R' -> existsb (Nat.eqb (ridx r)) qs = true -> getr R' r = getr R r.
Proof. intros qs R R' r H Hb. apply H. apply existsb_exists in Hb. destruct Hb as (q & Hq & Hb). apply Nat.eqb_eq in Hb. subst q. exact Hq. Qed.
Lemma m2_rp : forall (R R' : bvmap 5 word) (r : reg), regs_preserved R R' -> existsb (Z.eqb (bv_unsigned r)) callee_saved_idx = true -> getr R' r = getr R r.
Proof. intros R R' r H Hb. apply H. apply existsb_exists in Hb. destruct Hb as (q & Hq & Hb). apply Z.eqb_eq in Hb. rewrite Hb. exact Hq. Qed.
Lemma m2_kp : forall (qs : list nat) (R R' : bvmap 5 word), regs_preserved R R' -> forallb (fun q => existsb (Z.eqb (Z.of_nat q)) callee_saved_idx) qs = true -> TK.keepsR qs R R'.
Proof.
  intros qs R R' H Hb. apply TK.keepsR_preserved; [exact H|]. intros q Hq. rewrite forallb_forall in Hb. specialize (Hb q Hq).
  apply existsb_exists in Hb. destruct Hb as (z & Hz & Hzb). apply Z.eqb_eq in Hzb. rewrite Hzb. exact Hz.
Qed.
Lemma m2_src_x : forall (K : Z -> Prop) (M M' : mem) S IS ch bof, TK.samem K M M' -> 0 <= S < 2 ^ 59 -> TK2.cov K S 312 ->
  PMCS.src_at M S IS ch bof -> PMCS.src_at M' S IS ch bof.
Proof.
  intros K M M' S IS ch bof AG HS HC (A1 & A2 & A3 & A4 & (de & A5 & A5b) & A6 & A7 & (st0 & A8) & A9).
  assert (CV : forall o n, S <= o -> o + n <= S + 312 -> TK2.cov K o n) by (intros o n H1 H2 i Hi; apply HC; lia).
  refine (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ (conj _ _)))))))).
  - exact (TK2.u64_x K M M' AG (S + 240) _ ltac:(lia) (CV (S + 240) 8 ltac:(lia) ltac:(lia)) A1).
  - exact (TK2.u64_x K M M' AG (S + 248) _ ltac:(lia) (CV (S + 248) 8 ltac:(lia) ltac:(lia)) A2).
  - exact (TK2.u64_x K M M' AG (S + 264) _ ltac:(lia) (CV (S + 264) 8 ltac:(lia) ltac:(lia)) A3).
  - exact (TK2.u64_x K M M' AG (S + 272) _ ltac:(lia) (CV (S + 272) 8 ltac:(lia) ltac:(lia)) A4).
  - exists de. split; [exact (TK2.u64_x K M M' AG (S + 280) _ ltac:(lia) (CV (S + 280) 8 ltac:(lia) ltac:(lia)) A5) | exact A5b].
  - exact (TK2.u64_x K M M' AG (S + 288) _ ltac:(lia) (CV (S + 288) 8 ltac:(lia) ltac:(lia)) A6).
  - exact (TK2.u8_x K M M' AG (S + 296) _ ltac:(lia) (CV (S + 296) 1 ltac:(lia) ltac:(lia)) A7).
  - exists st0. exact (TK2.iosb_at_x K M M' AG (S + 88) _ _ ltac:(lia) (CV (S + 88) 152 ltac:(lia) ltac:(lia)) A8).
  - exact (TK2.u64_x K M M' AG (S + 32) _ ltac:(lia) (CV (S + 32) 8 ltac:(lia) ltac:(lia)) A9).
Qed.
