  lazymatch type of FRx with _ -> _ -> ?B => assert (FR'' : B) end.
  { apply FRx; [| intros a _ Hn; exact (MG67 _ Hn)].
    intros a Ha Hcl Hnf Hne. cbv beta in Hnf. split.
    - unfold CCS.KE6. split; [|split]; intros Hw.
      + apply Hnf. left. lia.
      + apply Hnf. left. lia.
      + destruct Hcl as [(bb & Hb & Hr) | [(Hc1 & Hc2) | (Hi1 & Hi2)]]; [destruct (BOK bb Hb) as (_ & _ & _ & _ & Hce); lia | lia | lia].
    - intros rr Hrr. cbn [In] in Hrr. destruct Hrr as [<- | [<- | []]]; unfold L5.in_rng; cbn [fst snd]; intros Hw.
      + destruct Hcl as [(bb & Hb & Hr) | [(Hc1 & Hc2) | (Hi1 & Hi2)]]; [destruct (BOK bb Hb) as (_ & _ & _ & _ & Hce); lia | lia | lia].
      + apply Hnf. right. lia. }
  pose proof (fun a Ha Ho H0 => MG67 _ (DW a Ha Ho H0)) as DW''.
  eapply (cc_syscat LB cr C IS E sp r kx bx rep g R0 M0 model0 K ch b p fx'' R'' M'' model).
  all: eassumption.
Qed.

Lemma m2_ksub : forall (qs qs' : list nat) (R R' : bvmap 5 word), TK.keepsR qs R R' -> forallb (fun q => existsb (Nat.eqb q) qs) qs' = true -> TK.keepsR qs' R R'.
Proof.
  intros qs qs' R R' H Hb r Hr. apply H. rewrite forallb_forall in Hb. specialize (Hb _ Hr).
  apply existsb_exists in Hb. destruct Hb as (q & Hq & Hqb). apply Nat.eqb_eq in Hqb. rewrite Hqb. exact Hq.
Qed.
Ltac m2_kst :=
  split; [let rr := fresh "rr" in let Hrr := fresh "Hrr" in intros rr Hrr; cbn [In] in Hrr; destruct Hrr as [<- | []]; unfold L5.in_rng; cbn [fst snd]; lia | left; lia].
Lemma cc_vrsv (LB : list (Z * Z)) (cr : credit) (C IS E sp r kx bx : Z) (rep : PML.srep) (g : PML.ls_state)
  (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K : ShapeAlg.TSet)
  (ch b p : Z) (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model)
  (Hcont : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LB' : list (Z * Z)) (cr' : credit) (LBk : list (Z * Z)) (W : list L5.range), PML.fp_ok fx' -> (exists (ch : Z) (ps' : PML.pstate) (code gp' rdst' : Z) (g' : PML.ls_state) (bof' dn' : bool), PMCS.cursor_at M' C IS ch bof' dn' ps' /\ PML.isrc_at M' IS rep gp' rdst' /\ PMCS.rn_bound ps' IS rep gp' (Z.of_nat (length (PML.srep_chars rep))) /\ PML.ec_at M' E code /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.regJ g) /\ PMCUR.wf_c ps' /\ PML.win_ok M' ((ch, 16384) :: LB) ps' /\ PML.u8 M' 0xd5030 1 /\ LB' = PML.ps_blocks ps' ++ (ch, 16384) :: LB /\ LBk = LB /\ PML.pcredit_x L cr' ps' kx bx /\ W = [(C, PMCS.CURSOR_SIZE); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] /\ (code = 0 -> dn' = false -> PML.ps_more ps' = false /\ ((PML.ps_done ps' = true /\ PML.ps_st ps' = PML.ST_DONE) \/ (PMCUR.wf_c (PMCUR.ps_set_more ps' true) /\ PMCS.evc M' (C + 592) 0 ((ch, 16384) :: LB) ps')))) -> regs_preserved R0 R' -> L5C.hpres L LBk sp (PMCS.CCTOR_SCR STRTOD_SCR) W M0 M' -> model_but_vm model0 model' -> hi_heap HI LB' cr' M' (m_vmmaps model') -> srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model') K)
  (Hmo : PML.model_ok model)
  (BV0 : model_but_vm model0 model)
  (HK0 : K [])
  (Hfp : PML.fp_ok fx)
  (H2 : getr R 2%bv = Z_to_bv 64 (sp - 496))
