  (HH : hi_heap HI ((b, 66) :: (p, 264) :: (ch, 16384) :: LB) (debit L (debit L (debit L cr 16384) 264) 66) M (m_vmmaps model))
  (SRC : PMCS.src_at M (C + 8) IS ch true)
  (PCL : exists Mp, CCS.pcells Mp (C + 320) /\ TK.samem (fun a => C + 320 <= a < C + 544) Mp M)
  (BUF : PML.str_at M (C + 544) (PML.SLong 264 p []))
  (DC : L5.defined M C 656)
