  (V1 : L5.u64_at RSEGS M (C + 576) b)
  (V2 : L5.u64_at RSEGS M (C + 584) (b + 66))
  (ISRC : PML.isrc_at M IS rep (PML.srep_data (IS + 80) rep) 0)
  (DEC : L5.defined M (sp - 384) 16)
