  { split; [apply CK.al16; [exact S1 | reflexivity]|]. split; [lia|]. split; [lia|]. split; [exact S4|]. intros i Hi. apply MG1. apply (proj2 FR). lia. }
  replace (C + 576) with (C + 568 + 8) in V1 by lia. replace (C + 584) with (C + 568 + 16) in V2 by lia.
  pose proof (TK2.u64_x _ M M1 SAM1 (C + 568) _ ltac:(lia) ltac:(intros i Hi; cbv beta; lia) V0) as V01.
  pose proof (TK2.u64_x _ M M1 SAM1 (C + 568 + 8) _ ltac:(lia) ltac:(intros i Hi; cbv beta; lia) V1) as V11.
  pose proof (TK2.u64_x _ M M1 SAM1 (C + 568 + 16) _ ltac:(lia) ltac:(intros i Hi; cbv beta; lia) V2) as V21.
  apply (VPUSH _ _ (C + 568) b 66 (sp - 481) 0 (sp - 496) CCT.R_PUSH [] fx1 R1 M1 model K HH1 Hmo HK0 Hfp1).
  { cbv beta.
    split; [split; [exact H11|]; split; [exact (ra_ok_lit CCT.R_PUSH eq_refl)|]; split; [exact H21|]; split; [exact H41 | exact STK1]|].
    split; [unfold PML.a0; rewrite H101; exact H23|]. split; [exact H111|]. split; [exact U481|]. split; [lia|].
    split; [exact V01|]. split; [replace (b + Z.of_nat (length (@nil Z))) with b by (cbn; lia); exact V11|]. split; [exact V21|].
    split; [intros i Hi; cbn in Hi; lia|]. split; [cbn [In]; left; reflexivity|]. split; [cbn; lia|]. split; [cbn; lia|].
    split; [split; [lia | split; [lia | apply al8_add; [exact OC3 | reflexivity]]] | intros Hz; cbn in Hz; lia]. }
  intros fx2 R2 M2 model2 LB2 cr2 LBk2 Wv Hfp2 PST RP2 HP2 BVm HH2.
