  assert (BLKr : TK2.blocks_ok L (lb_remove b ((b, 66) :: (p, 264) :: (ch, 16384) :: LB))) by (intros bb Hbb; exact (BLK bb (L5C.in_lb_remove b bb _ Hbb))).
  pose proof (TK2.hpres_samem L LAY _ _ _ _ M1 M2 HP2 BLKr STK1 HVEC0) as SAM2.
  pose proof (TK.samem_trans _ M M1 M2 (TK.samem_weaken _ (fun a => ~ (sp - 481 <= a < sp - 480) /\ TK2.keepH L (lb_remove b ((b, 66) :: (p, 264) :: (ch, 16384) :: LB)) [(C + 568, 24)] (sp - 496) PMS.VEC_SCR a) M M1 SAM1 (fun a H => proj1 H))
