  assert (STRC : TK2.str_cov (fun a => ~ (sp - 481 <= a < sp - 480) /\ TK2.keepH L (lb_remove b ((b, 66) :: (p, 264) :: (ch, 16384) :: LB)) [(C + 568, 24)] (sp - 496) PMS.VEC_SCR a) (IS + 80) rep).
  { pose proof CHF as CHF'. destruct rep as [s | cap q s]; cbn [PML.srep_blocks] in CHF'.
