    - intros a Ha. split; [lia | split; [intros rr Hrr; cbn [In] in Hrr; destruct Hrr as [<- | []]; unfold L5.in_rng; cbn [fst snd]; lia | right; right; right; lia]]. }
  pose proof (TK2.ls_ok_x _ M M2 SAM12 SC12 g LSg) as LSg2.
