  pose proof (TK2.u64_x _ M M2 SAM12 (sp - 256) _ ltac:(lia) ltac:(intros i Hi; split; [cbv beta; lia | m2_kst]) O48) as O482.
  pose proof (CCS.zeros_samem _ M M2 (sp - 224) 144 SAM12 ltac:(lia) ltac:(lia) ltac:(intros i Hi; split; [cbv beta; lia | m2_kst]) OZ) as OZ2.
  assert (WF2 : CCS.cells64 M2 (CCS.wframe sp r R0)).
  { apply (CCS.cells64_win _ M M2 _ (sp - 56) sp SAM12); [lia | lia | intros i Hi; split; [cbv beta; lia | m2_kst] | | exact WF].
