    intros av Hav. unfold CCS.pframe in Hav. cbn [In] in Hav. repeat destruct Hav as [<- | Hav]; try contradiction; cbn [fst]; lia. }
  pose proof (TK2.FR_grows L LAY LB sp (PMCS.CCTOR_SCR STRTOD_SCR) _ M0 M M1 _ FR SAM1 MG1 BOK ltac:(lia) ltac:(lia)
                ltac:(intros a Ha; left; cbv beta in Ha; lia)) as FR1.
  pose proof (TK2.FR_hpres L LAY LB sp (PMCS.CCTOR_SCR STRTOD_SCR) _ M0 M1 M2 _ _ _ _ FR1 HP2 BOK
                ltac:(intros [bb1 bbn] Hbb; apply L5C.in_lb_remove_neq; [right; right; right; exact Hbb | exact (NB _ (or_intror (or_intror Hbb)))])
                ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) HVEC0
                ltac:(intros w a Hw Hin; cbn [In] in Hw; destruct Hw as [<- | []]; unfold L5.in_rng in Hin; cbn [fst snd] in Hin; right; cbv beta; left; lia)) as FR2.
  apply (cc_push LB cr C IS E sp r kx bx rep g R0 M0 model0 K ch b p fx2 R2 M2 model2) with (p6 := p6).
  all: try eassumption.
  intros a Ha Ho H0. pose proof (DW a Ha Ho H0) as Hm. destruct (not_outside _ _ Ho) as (w & Hw & Hin). cbn [In] in Hw.
  destruct Hw as [<- | [<- | [<- | [<- | [<- | [<- | []]]]]]]; unfold L5.in_rng in Hin; cbn [fst snd] in Hin.
  all: first
    [ apply GR12; [lia | exact Hm]
    | (rewrite (SAM12 a Ha); [exact Hm | cbv beta; split; [lia | split; [intros rr Hrr; cbn [In] in Hrr; destruct Hrr as [<- | []]; unfold L5.in_rng; cbn [fst snd]; lia | right; right; right; lia]]]) ].
Qed.

Lemma wa_statics_cov : forall K : Z -> Prop, (forall a, 0x10000 <= a < 0xf6c08 -> ~ (0xd675c <= a < 0xd6760) -> K a) -> TK2.statics_cov K.
Proof.
  intros K H. split; [|split].
  - intros a (iv & Hiv & Hr). apply H; unfold PML.ll_foot_csrc in Hiv; repeat (destruct Hiv as [<-|Hiv]; [cbn in Hr; lia|]); destruct Hiv.
  - intros a Ha. unfold PML.IMG_RO_HI in Ha. apply H; lia.
  - intros a Ha. apply H; lia.
Qed.
Lemma wa_kr : forall (R R' : bvmap 5 word) qs (r : reg), TK.keepsR qs R R' -> In (ridx r) qs -> getr R' r = getr R r.
Proof. intros R R' qs r H Hb. apply H. exact Hb. Qed.
Lemma cc_rsv (LB : list (Z * Z)) (cr : credit) (C IS E sp r kx bx : Z) (rep : PML.srep) (g : PML.ls_state)
  (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K : ShapeAlg.TSet)
  (ch p : Z) (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model)
  (Hcont : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LB' : list (Z * Z)) (cr' : credit) (LBk : list (Z * Z)) (W : list L5.range), PML.fp_ok fx' -> (exists (ch : Z) (ps' : PML.pstate) (code gp' rdst' : Z) (g' : PML.ls_state) (bof' dn' : bool), PMCS.cursor_at M' C IS ch bof' dn' ps' /\ PML.isrc_at M' IS rep gp' rdst' /\ PMCS.rn_bound ps' IS rep gp' (Z.of_nat (length (PML.srep_chars rep))) /\ PML.ec_at M' E code /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.regJ g) /\ PMCUR.wf_c ps' /\ PML.win_ok M' ((ch, 16384) :: LB) ps' /\ PML.u8 M' 0xd5030 1 /\ LB' = PML.ps_blocks ps' ++ (ch, 16384) :: LB /\ LBk = LB /\ PML.pcredit_x L cr' ps' kx bx /\ W = [(C, PMCS.CURSOR_SIZE); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] /\ (code = 0 -> dn' = false -> PML.ps_more ps' = false /\ ((PML.ps_done ps' = true /\ PML.ps_st ps' = PML.ST_DONE) \/ (PMCUR.wf_c (PMCUR.ps_set_more ps' true) /\ PMCS.evc M' (C + 592) 0 ((ch, 16384) :: LB) ps')))) -> regs_preserved R0 R' -> L5C.hpres L LBk sp (PMCS.CCTOR_SCR STRTOD_SCR) W M0 M' -> model_but_vm model0 model' -> hi_heap HI LB' cr' M' (m_vmmaps model') -> srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model') K)
  (Hmo : PML.model_ok model)
  (BV0 : model_but_vm model0 model)
  (HK0 : K [])
  (Hfp : PML.fp_ok fx)
  (H2 : getr R 2%bv = Z_to_bv 64 (sp - 496))
