  (DC : L5.defined M C 656)
  (p6 : Z) (Hp6 : 0 <= p6 < 2 ^ 64)
  (PF : CCS.cells64 M (CCS.pframe sp C E p6 (bv_unsigned (getr R0 23%bv)))) :
  srealizes RSEGS SCFG (@PML.cfg fx R CCT.R_RSV M model) K.
Proof.
