  replace (sp - 304 + 80) with (sp - 224) in OZ by lia.
  assert (STKv : L5C.stk (hl_sptop L) M (sp - 496) PMS.VEC_SCR).
  { split; [apply CK.al16; [exact S1 | reflexivity]|]. split; [lia|]. split; [lia|]. split; [exact S4|]. intros i Hi. apply (proj2 FR). lia. }
  assert (BOK1 : TK2.blocks_ok L ((p, 264) :: (ch, 16384) :: LB)) by exact (TK2.blocks_ok_heap L HI HIok _ _ _ _ HH).
  assert (V0 : L5.u64_at RSEGS M (C + 568) 0) by (replace (C + 568) with (C + 568 + 0) by lia; apply (CCS.zeros_u64 _ _ _ 0 VZ); lia).
