  assert (KL0 : 0 <= kl) by (unfold kl; vm_compute; discriminate).
  assert (BL0 : 0 <= bl) by (unfold bl; vm_compute; discriminate).
  apply (CCS.s_r_rsv FPM fx R M model K sp Hh Hl Hfp H2 SPOK ltac:(lia) H19 O0 O224 RO).
