  apply (VRSV ((p, 264) :: (ch, 16384) :: LB) (debit L (debit L cr 16384) 264) (C + 568) (sp - 496) CCT.R_VRSV fx1 R1 M model K HH (conj Hh (conj Hl Hmat)) HK0 Hfp1).
  { split; [exact (CK.mk_entry L R1 M (sp - 496) _ _ H1a (ra_ok_lit CCT.R_VRSV eq_refl) H2a TP1 STKv)|].
    split; [exact H10v|]. split; [exact H11a|]. split; [exact V0|]. split; [exact V8|]. split; [exact V16|].
    split; [unfold PML.obj_on_stack; split; [lia | split; [lia | apply al8_add; [exact OC3 | reflexivity]]]|].
    unfold credit_ok, debit; cbn [fst snd]. nia. }
  intros fx2 R2 M2 model2 LB2 cr2 LBk2 W2 Hfp2 (b & VB0 & VB8 & VB16 & FB & -> & -> & -> & ->) RP2 HP2 BV2 HH2.
  assert (Hh2 : m_halted model2 = None) by (rewrite (L5C.halted_but_vm _ _ BV2); exact Hh).
  assert (Hl2 : m_vm_lazy model2 = []) by (rewrite (L5C.lazy_but_vm _ _ BV2); exact Hl).
  assert (Hmat2 : m_vm_materialized model2 = []) by (rewrite (L5C.materialized_but_vm _ _ BV2); exact Hmat).
  pose proof (TK2.hpres_samem L LAY _ _ _ _ M M2 HP2 BOK1 STKv ltac:(lia)) as AG2.
  assert (KH2 : forall a, sp - 496 <= a < hl_sptop L -> ~ (C + 568 <= a < C + 592) ->
