  { intros a Ha X. split; [|left; lia]. intros w Hw Hin. unfold L5.in_rng in Hin. destruct Hw as [<-|[]]; cbn [fst snd] in Hin; lia. }
  assert (KS2 : forall a, 0x10000 <= a < 0xf6c08 -> ~ (0xd675c <= a < 0xd6760) ->
