    repeat (destruct Hin as [<-|Hin]; [cbn [fst]; split; [lia | intros i Hi; apply KH2; lia]|]). destruct Hin. }
  assert (PF2 : CCS.cells64 M2 (CCS.pframe sp C E p6 (bv_unsigned (getr R0 23%bv)))).
  { apply (CCS.cells64_x _ M M2 _ AG2); [|exact PF]. intros av Hin. unfold CCS.pframe in Hin. cbn [In] in Hin.
    repeat (destruct Hin as [<-|Hin]; [cbn [fst]; split; [lia | intros i Hi; apply KH2; lia]|]). destruct Hin. }
  assert (O16_2 : L5.u64_at RSEGS M2 (sp - 288) PML.VT_FUNC) by (apply (TK2.u64_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact O16]).
  assert (O48_2 : L5.u64_at RSEGS M2 (sp - 256) (sp - 288)) by (apply (TK2.u64_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact O48]).
  assert (OZ2 : CCS.zeros M2 (sp - 224) 144) by (apply (CCS.zeros_samem _ M M2 _ _ AG2); [lia | lia | intros i Hi; apply KH2; lia | exact OZ]).
  assert (BUF2 : PML.str_at M2 (C + 544) (PML.SLong 264 p [])).
