    split; [intros i Hi; apply KH2; lia|]. split; [lia|]. split; [lia|]. intros i Hi. apply (KB2 p 264); [left; reflexivity | lia]. }
  assert (SRC2 : PMCS.src_at M2 (C + 8) IS ch true).
  { unfold PMCS.src_at. replace (C + 8 + 240) with (C + 248) by lia. replace (C + 8 + 248) with (C + 256) by lia.
    replace (C + 8 + 264) with (C + 272) by lia. replace (C + 8 + 272) with (C + 280) by lia. replace (C + 8 + 280) with (C + 288) by lia.
    replace (C + 8 + 288) with (C + 296) by lia. replace (C + 8 + 296) with (C + 304) by lia. replace (C + 8 + 88) with (C + 96) by lia.
    replace (C + 8 + 24) with (C + 32) by lia. replace (C + 8 + 32) with (C + 40) by lia.
    split; [apply (TK2.u64_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact S248]|].
    split; [apply (TK2.u64_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact S256]|].
    split; [apply (TK2.u64_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact S272]|].
    split; [apply (TK2.u64_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact S280]|].
    split; [exists ch; split; [apply (TK2.u64_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact S288] | lia]|].
    split; [apply (TK2.u64_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact S296]|].
    split; [apply (TK2.u8_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact S304]|].
    split; [exists 0; apply (TK2.iosb_at_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact IOSB]|].
    apply (TK2.u64_x _ M M2 AG2); [lia | intros i Hi; apply KH2; lia | exact LOC]. }
  assert (PCL2 : exists Mp, CCS.pcells Mp (C + 320) /\ TK.samem (fun a => C + 320 <= a < C + 544) Mp M2).
  { destruct PCL as (Mp & PP & AGp). exists Mp. split; [exact PP|].
    apply (CK.samem_weaken2 _ _ _ _ _ _ AGp AG2). intros a Ha. split; [exact Ha | apply KH2; lia]. }
  assert (CL2 : forall a, sp - SCR <= a < hl_sptop L -> ~ (sp - 496 - PMS.VEC_SCR <= a < sp - 496) ->
            HeapIface.client_addr L ((p, 264) :: (ch, 16384) :: LB) (sp - 496) PMS.VEC_SCR a).
  { intros a Ha X. unfold HeapIface.client_addr. right; left; lia. }
  assert (DC2 : L5.defined M2 C 656).
  { intros i Hi. apply (L5C.hpres_cdef _ _ _ _ _ _ _ (C + i) HP2); [lia | apply CL2; lia | unfold in_errno; rewrite ERR; lia | apply DC; exact Hi]. }
  assert (D384_2 : L5.defined M2 (sp - 384) 16).
  { intros i Hi. apply (L5C.hpres_cdef _ _ _ _ _ _ _ (sp - 384 + i) HP2); [lia | apply CL2; lia | unfold in_errno; rewrite ERR; lia | apply (proj2 FR); lia]. }
  assert (SC2 : TK2.statics_cov (TK2.keepH L ((p, 264) :: (ch, 16384) :: LB) [(C + 568, 24)] (sp - 496) PMS.VEC_SCR)) by (apply wa_statics_cov; exact KS2).
  assert (GU2 : (PML.u8 M2 0xd5030 0 /\ PML.u8 M2 0xd5031 0) \/ PML.u8 M2 0xd5030 1).
  { destruct GU as [(G0 & G1) | G0]; [left; split | right];
