  assert (ISRC2 : PML.isrc_at M2 IS rep (PML.srep_data (IS + 80) rep) 0).
  { apply (TK2.isrc_at_x _ M M2 AG2); [lia | intros i Hi; apply KH2; unfold box in APCI; lia | | exact ISRC].
    split; [intros i Hi; apply KH2; unfold box in APCI; lia|]. destruct rep as [s | cap q s]; [exact I|].
    destruct (CHF (q, cap) (or_introl eq_refl)) as (Hq & _).
    pose proof (BOK1 (q, cap) (or_intror Hq)) as (B0 & B1 & B2 & B3 & B4). cbn [fst snd] in *.
    split; [lia|]. split; [lia|]. intros i Hi. apply (KB2 q cap); [right; exact Hq | lia]. }
  assert (LS2 : PML.ls_ok g M2) by exact (TK2.ls_ok_x _ M M2 AG2 SC2 g LSg).
  assert (RO2 : PML.img_ro M2) by exact (TK2.img_ro_x _ M M2 AG2 SC2 RO).
  assert (EC2 : PML.ec_at M2 E 0) by (apply (TK2.ec_at_x _ M M2 AG2); [lia | intros i Hi; apply KH2; unfold box in APCE; lia | exact EC0]).
  assert (FR2 : TK2.FR L LB sp (PMCS.CCTOR_SCR STRTOD_SCR) (fun a => C <= a < C + 656 \/ 0xd5030 <= a < 0xd5032) M0 M2).
  { apply (TK2.FR_hpres L LAY LB sp SCR _ M0 M M2 ((p, 264) :: (ch, 16384) :: LB) (sp - 496) PMS.VEC_SCR _ FR HP2 BOK
             ltac:(intros q Hq; right; right; exact Hq)); [lia | lia | lia | lia | lia | lia |].
