  assert (DW2 : forall a, 0 <= a < 2 ^ 64 -> ~ L5.outside [(C, 656); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] a -> M0 (Z_to_bv 64 a) <> None -> M2 (Z_to_bv 64 a) <> None).
  { intros a Ha HO Hd. apply (L5C.hpres_cdef _ _ _ _ _ _ _ a HP2 Ha); [| | exact (DW a Ha HO Hd)].
    - destruct (not_outside _ _ HO) as (w & Hw & Hin). unfold L5.in_rng in Hin. unfold HeapIface.client_addr. rewrite ILO, IHI.
      destruct Hw as [<-|[<-|[<-|[<-|[<-|[<-|[]]]]]]]; cbn [fst snd] in Hin;
        [right; left; lia | right; left; lia | right; left; lia | right; right; split; [lia | intros Z0; apply (PmLayout.ly_static L LAY) in Z0; lia] ..].
    - destruct (not_outside _ _ HO) as (w & Hw & Hin). unfold L5.in_rng in Hin. unfold in_errno. rewrite ERR.
      destruct Hw as [<-|[<-|[<-|[<-|[<-|[<-|[]]]]]]]; cbn [fst snd] in Hin; lia. }
  assert (KR2 : TK.keepsR [2; 4; 23]%nat R1 R2) by (apply (ko_rp _ _ _ RP2); reflexivity).
  assert (H2b : getr R2 2%bv = Z_to_bv 64 (sp - 496)) by (rewrite (KR2 2%bv ltac:(ck_in)); exact H2a).
  assert (H4b : getr R2 4%bv = Z_to_bv 64 PML.TP) by (rewrite (KR2 4%bv ltac:(ck_in)); exact TP1).
  assert (H23b : getr R2 23%bv = Z_to_bv 64 (C + 568)) by (rewrite (KR2 23%bv ltac:(ck_in)), (KO1 23%bv ltac:(ck_in)); exact H23).
  assert (KOR2 : TK.keepsR CCS.KO8 R0 R2).
  { assert (S84 : forall q, In q CCS.KO8 -> In q CCS.KO4) by (intros q Hq; unfold CCS.KO8, CCS.KO4 in *; cbn [In] in *; intuition).
    apply (TK.keepsR_trans _ _ _ _ KOR). apply (TK.keepsR_trans _ _ _ _ (CK.keepsR_sub _ _ _ _ KO1 S84)).
    apply (ko_rp _ _ _ RP2). reflexivity. }
  assert (PC2 : PML.pcredit_x L (debit L (debit L (debit L cr 16384) 264) 66) (PMS.ps_init b p) kx bx).
  { unfold PML.pcredit_x, PML.pcredit, debit. cbn [fst snd].
    change (PML.kleft (PMS.ps_init b p)) with kl. change (PML.bleft (PMS.ps_init b p)) with bl.
    split; [exact CK1|]. split; [exact CK2|]. split; [cbn; lia|]. split; nia. }
  replace (C + 568 + 8) with (C + 576) in VB8 by lia. replace (C + 568 + 16) with (C + 584) in VB16 by lia.
  apply (cc_vrsv LB cr C IS E sp r kx bx rep g R0 M0 model0 K ch b p fx2 R2 M2 model2 Hcont (conj Hh2 (conj Hl2 Hmat2)) (L5C.model_but_vm_trans _ _ _ BV0 BV2) HK0 Hfp2
           H2b H4b H23b KOR2 H2R0 HH2 SRC2 PCL2 BUF2 DC2 VB0 VB8 VB16 ISRC2 D384_2 CHF NLEN LS2 HG PC2 STK0 Hrok OC OI OE APCI APCE APIE WF2 CF2 O16_2 O48_2 OZ2
           RO2 GU2 EC2 FR2 DW2 BOK p6 Hp6 PF2).
Qed.

Lemma w9_out1 : forall a b n, a < b \/ b + n <= a -> L5.outside [(b, n)] a.
Proof. intros a b n H w Hw. destruct Hw as [<-|[]]. unfold L5.in_rng. cbn [fst snd]. lia. Qed.
Lemma cc_new (LB : list (Z * Z)) (cr : credit) (C IS E sp r kx bx : Z) (rep : PML.srep) (g : PML.ls_state)
  (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K : ShapeAlg.TSet)
  (ch : Z) (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model)
  (Hcont : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LB' : list (Z * Z)) (cr' : credit) (LBk : list (Z * Z)) (W : list L5.range), PML.fp_ok fx' -> (exists (ch : Z) (ps' : PML.pstate) (code gp' rdst' : Z) (g' : PML.ls_state) (bof' dn' : bool), PMCS.cursor_at M' C IS ch bof' dn' ps' /\ PML.isrc_at M' IS rep gp' rdst' /\ PMCS.rn_bound ps' IS rep gp' (Z.of_nat (length (PML.srep_chars rep))) /\ PML.ec_at M' E code /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.regJ g) /\ PMCUR.wf_c ps' /\ PML.win_ok M' ((ch, 16384) :: LB) ps' /\ PML.u8 M' 0xd5030 1 /\ LB' = PML.ps_blocks ps' ++ (ch, 16384) :: LB /\ LBk = LB /\ PML.pcredit_x L cr' ps' kx bx /\ W = [(C, PMCS.CURSOR_SIZE); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] /\ (code = 0 -> dn' = false -> PML.ps_more ps' = false /\ ((PML.ps_done ps' = true /\ PML.ps_st ps' = PML.ST_DONE) \/ (PMCUR.wf_c (PMCUR.ps_set_more ps' true) /\ PMCS.evc M' (C + 592) 0 ((ch, 16384) :: LB) ps')))) -> regs_preserved R0 R' -> L5C.hpres L LBk sp (PMCS.CCTOR_SCR STRTOD_SCR) W M0 M' -> model_but_vm model0 model' -> hi_heap HI LB' cr' M' (m_vmmaps model') -> srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model') K)
  (Hmo : PML.model_ok model)
  (BV0 : model_but_vm model0 model)
  (HK0 : K [])
  (Hfp : PML.fp_ok fx)
  (H2 : getr R 2%bv = Z_to_bv 64 (sp - 432))
  (H4 : getr R 4%bv = Z_to_bv 64 PML.TP)
  (H9 : getr R 9%bv = Z_to_bv 64 (C + 8))
  (H10 : getr R 10%bv = Z_to_bv 64 ch)
  (H20 : getr R 20%bv = Z_to_bv 64 (sp - 304))
  (KOR : TK.keepsR CCS.KO7 R0 R)
  (H2R0 : getr R0 2%bv = Z_to_bv 64 sp)
  (HH : hi_heap HI ((ch, 16384) :: LB) (debit L cr 16384) M (m_vmmaps model))
  (IOSB : PML.iosb_at M (C + 96) 0 (C + 32))
  (LOC : PML.u64 M (C + 40) PML.CLASSIC_IMP)
  (S248 : L5.u64_at RSEGS M (C + 248) IS)
  (S256 : L5.u64_at RSEGS M (C + 256) (IS + 16))
  (S280 : L5.u64_at RSEGS M (C + 280) 16384)
  (S296 : L5.u64_at RSEGS M (C + 296) 0)
  (ISRC : PML.isrc_at M IS rep (PML.srep_data (IS + 80) rep) 0)
  (GU : (PML.u8 M 0xd5030 0 /\ PML.u8 M 0xd5031 0) \/ PML.u8 M 0xd5030 1)
  (CHF : forall b0, In b0 (PML.srep_blocks rep) -> In b0 ((ch, 16384) :: LB) /\ fst b0 <> ch)
  (NLEN : Z.of_nat (length (PML.srep_chars rep)) < 2 ^ 26)
  (LSg : PML.ls_ok g M)
  (HG : g <> PML.LS0)
  (CRS : 0 <= kx /\ 0 <= bx /\ 3 * hl_k_per_malloc L + PML.kleft (PMS.ps_init 0 0) * hl_k_per_malloc L + kx <= fst cr /\ 16384 + 264 + 66 + 3 * hl_b_overhead L + PML.bleft (PMS.ps_init 0 0) + PML.kleft (PMS.ps_init 0 0) * hl_b_overhead L + bx <= snd cr)
  (STK0 : L5C.stk (hl_sptop L) M0 sp (PMCS.CCTOR_SCR STRTOD_SCR))
  (Hrok : L5.ra_ok r)
  (OC : PML.obj_on_stack L sp C 656)
  (OI : PML.obj_on_stack L sp IS 272)
  (OE : PML.obj_on_stack L sp E 16)
  (APCI : box (C + 656 <= IS \/ IS + 272 <= C))
  (APCE : box (C + 656 <= E \/ E + 16 <= C))
  (APIE : box (IS + 272 <= E \/ E + 16 <= IS))
  (WF : CCS.cells64 M (CCS.wframe sp r R0))
  (CF : CCS.cells64 M (CCS.cframe sp C IS E (bv_unsigned (getr R0 22%bv))))
  (OPT : CCS.opts_at M (sp - 304))
  (SF : CCS.cells64 M (CCS.sframe sp C E))
  (RO : PML.img_ro M)
  (EC0 : PML.ec_at M E 0)
  (FR : TK2.FR L LB sp (PMCS.CCTOR_SCR STRTOD_SCR) (fun a => C <= a < C + 656 \/ 0xd5030 <= a < 0xd5032) M0 M)
  (DW : forall a, 0 <= a < 2 ^ 64 -> ~ L5.outside [(C, 656); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] a -> M0 (Z_to_bv 64 a) <> None -> M (Z_to_bv 64 a) <> None)
  (BOK : TK2.blocks_ok L LB)
  (DC0 : L5.defined M0 C 656) :
  srealizes RSEGS SCFG (@PML.cfg fx R CCT.R_NEW M model) K.
Proof.
  pose proof STK0 as (S1 & S2 & S3 & S4 & S5).
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI. pose proof (PmLayout.ly_errno L LAY) as ERR.
  pose proof (PmLayout.ly_kpm L LAY) as KPM. pose proof (PmLayout.ly_bov L LAY) as BOV.
  set (SCR := PMCS.CCTOR_SCR STRTOD_SCR) in *.
  assert (HSCR : 496 + PMS.STR_SCR <= SCR /\ 528 <= PMS.STR_SCR).
  { unfold SCR, PMCS.CCTOR_SCR, PMCS.CCTOR_MAIN_SCR, PMS.STR_SCR, PMS.CTOR_SCR, PMS.OPNEW_SCR, PML.HEAP_STACK. lia. }
  destruct HSCR as (HSCR & HSTR).
  assert (SPOK : CK.spok sp) by (split; [lia | exact S1]).
  pose proof Hmo as (Hh & Hl & Hmat).
  pose proof OC as (OC1 & OC2 & OC3). pose proof OI as (OI1 & OI2 & OI3). pose proof OE as (OE1 & OE2 & OE3).
  assert (APCI' : C + 656 <= IS \/ IS + 272 <= C) by exact APCI.
  assert (APCE' : C + 656 <= E \/ E + 16 <= C) by exact APCE.
  match type of HH with hi_heap _ ((_, ?n) :: _) _ _ _ => pose (N := n) end.
  pose proof (TK2.blocks_ok_heap L HI HIok _ _ _ _ HH) as HB.
  pose proof (HB _ (or_introl eq_refl)) as (B0 & B1 & B2 & B3 & B4). cbn [fst snd] in B0, B1, B2, B3, B4.
  assert (DC : L5.defined M C 656).
  { intros i Hi. apply (DW (C + i)); [lia | | apply DC0; exact Hi]. intros X. apply (X (C, 656)); [left; reflexivity | unfold L5.in_rng; cbn [fst snd]; lia]. }
  assert (DF : L5.defined M (sp - 528) 128) by (intros i Hi; apply (proj2 FR); lia).
  assert (R23 : getr R 23%bv = getr R0 23%bv) by (apply KOR; ck_in).
  apply (CCS.s_r_new FPM fx R M model K sp C ch E Hh Hl Hfp H2 SPOK H10 H9 H20 ltac:(lia) OC3 ltac:(lia) ltac:(lia) OC1 SF OPT RO DC DF).
  intros fx1 R1 M1 Hfp1 H2a H1a H10a H11a H19a H23a KOa PF1 C272 C288 C304 PC1 AG1 MG1.
  assert (H4a : getr R1 4%bv = Z_to_bv 64 PML.TP) by (rewrite (KOa 4%bv ltac:(ck_in)); exact H4).
  assert (STK1 : L5C.stk (hl_sptop L) M1 (sp - 496) PMS.STR_SCR).
  { split; [apply CK.al16; [exact S1 | reflexivity]|]. split; [lia|]. split; [lia|]. split; [exact S4|]. intros i Hi. apply MG1. apply (proj2 FR). lia. }
  assert (AG1' : TK.samem (fun a => ~ (sp - 528 <= a < hl_sptop L)) M M1).
  { apply (TK.samem_weaken _ _ _ _ AG1). intros a Ha. unfold CCS.KE4. lia. }
  pose proof (TK2.heap_stack_write L HI HIok LAY _ _ M M1 _ (sp - 528) (hl_sptop L) HH ltac:(lia) ltac:(lia) ltac:(lia) AG1' MG1) as HH1.
  pose proof PC1 as PCs.
  destruct PC1 as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & P224).
  apply (STRRSV ((ch, N) :: LB) (debit L cr N) (C + 544) (sp - 496) CCT.R_RSV fx1 R1 M1 model K HH1 Hmo HK0 Hfp1).
  { split; [exact (CK.mk_entry L R1 M1 (sp - 496) _ _ H1a (ra_ok_lit CCT.R_RSV eq_refl) H2a H4a STK1)|].
    split; [exact H10a|]. split; [exact H11a|].
    assert (Z544 : forall k, 0 <= k -> k + 8 <= 48 -> L5.u64_at RSEGS M1 (C + 544 + k) 0).
    { intros k Hk0 Hk1. replace (C + 544 + k) with (C + 320 + 224 + k) by lia. exact (CCS.zeros_u64 M1 (C + 320 + 224) 48 k P224 Hk0 Hk1). }
    split; [rewrite <- (Z.add_0_r (C + 544)); apply Z544; lia|].
    split; [apply Z544; lia|]. split; [apply Z544; lia|].
    split; [unfold PML.obj_on_stack; split; [lia | split; [lia | apply (CCS.al8_lin C _ 68 OC3); lia]]|].
    unfold credit_ok, debit. cbn [fst snd].
    assert (KL : 0 <= PML.kleft (PMS.ps_init 0 0)) by (vm_compute; intros X; discriminate X).
    assert (BL : 0 <= PML.bleft (PMS.ps_init 0 0)) by (vm_compute; intros X; discriminate X).
    pose proof (Z.mul_nonneg_nonneg _ _ KL KPM) as KM1. pose proof (Z.mul_nonneg_nonneg _ _ KL BOV) as KM2.
    destruct CRS as (CR1 & CR2 & CR3 & CR4). unfold N. lia. }
  intros fx2 R2 M2 model2 LB2 cr2 LBk2 W2 Hfp2 (p & STR2 & FB2 & -> & -> & -> & ->) RP2 HP2 BV2 HH2.
  pose proof (TK2.hpres_samem L LAY _ _ _ _ M1 M2 HP2 HB STK1 ltac:(lia)) as AG2.
  assert (KH2 : forall a, sp - 496 <= a -> ~ (C + 544 <= a < C + 568) -> TK2.keepH L ((ch, N) :: LB) [(C + 544, 24)] (sp - 496) PMS.STR_SCR a).
  { intros a Ha1 Ha2. unfold TK2.keepH. split; [apply w9_out1; lia | left; lia]. }
  pose (K12 := fun a => CCS.KE4 sp C a /\ TK2.keepH L ((ch, N) :: LB) [(C + 544, 24)] (sp - 496) PMS.STR_SCR a).
  assert (AG12 : TK.samem K12 M M2) by exact (CK.samem_weaken2 _ _ K12 M M1 M2 AG1 AG2 (fun a H => H)).
  assert (KK : forall a, sp - 496 <= a -> CCS.KE4 sp C a -> ~ (C + 544 <= a < C + 568) -> K12 a).
  { intros a Ha1 Ha2 Ha3. unfold K12. split; [exact Ha2 | apply KH2; lia]. }
  assert (DC2 : L5.defined M2 C 656).
  { intros i Hi. apply (L5C.hpres_cdef _ _ _ _ _ _ _ (C + i) HP2); [lia | right; left; split; lia | unfold in_errno; rewrite ERR; lia | apply MG1; apply DC; exact Hi]. }
  assert (WF2 : CCS.cells64 M2 (CCS.wframe sp r R0)).
  { apply (CCS.cells64_x _ M M2 _ AG12); [|exact WF]. intros av Hin. unfold CCS.wframe in Hin. cbn [In] in Hin.
    repeat (destruct Hin as [<-|Hin]; [cbn [fst]; split; [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia]]|]). destruct Hin. }
  assert (CF2 : CCS.cells64 M2 (CCS.cframe sp C IS E (bv_unsigned (getr R0 22%bv)))).
  { apply (CCS.cells64_x _ M M2 _ AG12); [|exact CF]. intros av Hin. unfold CCS.cframe in Hin. cbn [In] in Hin.
    repeat (destruct Hin as [<-|Hin]; [cbn [fst]; split; [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia]]|]). destruct Hin. }
  assert (OPT2 : CCS.opts_at M2 (sp - 304)).
  { apply (CCS.opts_at_x _ M M2 _ AG12); [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia] | exact OPT]. }
  assert (IOSB2 : PML.iosb_at M2 (C + 96) 0 (C + 32)).
  { apply (iosb_at_xd _ M M2 _ _ _ AG12); [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia] | eapply L5.defined_sub; [exact DC2 | lia | lia] | exact IOSB]. }
  assert (LOC2 : PML.u64 M2 (C + 40) PML.CLASSIC_IMP).
  { apply (TK2.u64_x _ M M2 AG12); [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia] | exact LOC]. }
  assert (S248b : L5.u64_at RSEGS M2 (C + 248) IS).
  { apply (TK2.u64_x _ M M2 AG12); [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia] | exact S248]. }
  assert (S256b : L5.u64_at RSEGS M2 (C + 256) (IS + 16)).
  { apply (TK2.u64_x _ M M2 AG12); [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia] | exact S256]. }
  assert (S280b : L5.u64_at RSEGS M2 (C + 280) N).
  { apply (TK2.u64_x _ M M2 AG12); [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia] | exact S280]. }
  assert (S296b : L5.u64_at RSEGS M2 (C + 296) 0).
  { apply (TK2.u64_x _ M M2 AG12); [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia] | exact S296]. }
  assert (S272b : L5.u64_at RSEGS M2 (C + 272) ch) by (apply (TK2.u64_x _ M1 M2 AG2); [lia | intros i Hi; apply KH2; lia | exact C272]).
  assert (S288b : L5.u64_at RSEGS M2 (C + 288) ch) by (apply (TK2.u64_x _ M1 M2 AG2); [lia | intros i Hi; apply KH2; lia | exact C288]).
  assert (S304b : L5.u8_at RSEGS M2 (C + 304) 1) by (apply (TK2.u8_x _ M1 M2 AG2); [lia | intros i Hi; apply KH2; lia | exact C304]).
  assert (VZ2 : CCS.zeros M2 (C + 568) 24).
  { apply (CCS.zeros_samem _ M1 M2 _ _ AG2); [lia | lia | intros i Hi; apply KH2; lia | eapply CCS.zeros_sub; [exact P224 | lia | lia]]. }
  assert (PCL2 : exists Mp, CCS.pcells Mp (C + 320) /\ TK.samem (fun a => C + 320 <= a < C + 544) Mp M2).
  { exists M1. split; [exact PCs|]. apply (TK.samem_weaken _ _ _ _ AG2). intros a Ha. cbv beta in Ha. apply KH2; lia. }
  assert (ISRC2 : PML.isrc_at M2 IS rep (PML.srep_data (IS + 80) rep) 0).
  { apply (TK2.isrc_at_x _ M M2 AG12); [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia] | | exact ISRC].
    split; [intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia]|].
    destruct rep as [s0|cap q s0]; [exact I|].
    destruct (CHF (q, cap) (or_introl eq_refl)) as (Hq & _). pose proof (HB _ Hq) as (Q0 & Q1 & Q2 & Q3 & Q4). cbn [fst snd] in Q0, Q1, Q2, Q3, Q4.
    split; [lia|]. split; [lia|]. intros i Hi. unfold K12. split; [unfold CCS.KE4; lia|].
    unfold TK2.keepH. split; [apply w9_out1; lia | right; right; left; exists (q, cap); split; [exact Hq | cbn [fst snd]; lia]]. }
  assert (EC2 : PML.ec_at M2 E 0).
  { apply (TK2.ec_at_x _ M M2 AG12); [lia | intros i Hi; apply KK; [lia | unfold CCS.KE4; lia | lia] | exact EC0]. }
  assert (SC1 : TK2.statics_cov (CCS.KE4 sp C)) by (apply TK2.statics_cov_lo; intros a Ha; unfold CCS.KE4; lia).
  assert (SC2 : TK2.statics_cov (TK2.keepH L ((ch, N) :: LB) [(C + 544, 24)] (sp - 496) PMS.STR_SCR)).
  { apply TK2.statics_cov_keepH. intros a Ha w [<-|[]] Hin. unfold L5.in_rng in Hin. cbn [fst snd] in Hin.
    destruct Ha as [(iv & Hiv & Hr)|Hr]; [unfold PML.ll_foot_csrc in Hiv; repeat (destruct Hiv as [<-|Hiv]; [cbn [fst snd] in Hr; lia|]); destruct Hiv | unfold PML.IMG_RO_HI in Hr; lia]. }
  pose proof (TK2.img_ro_x _ M1 M2 AG2 SC2 (TK2.img_ro_x _ M M1 AG1 SC1 RO)) as RO2.
  pose proof (TK2.ls_ok_x _ M1 M2 AG2 SC2 g (TK2.ls_ok_x _ M M1 AG1 SC1 g LSg)) as LS2.
  pose proof (TK2.FR_grows L LAY _ _ _ _ M0 M M1 _ FR AG1 MG1 BOK ltac:(lia) ltac:(lia) ltac:(intros a Ha; cbv beta; unfold CCS.KE4 in Ha; lia)) as FR1.
  pose proof (TK2.FR_hpres L LAY _ _ _ _ M0 M1 M2 _ (sp - 496) PMS.STR_SCR _ FR1 HP2 BOK (incl_tl _ (incl_refl LB)) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)
                ltac:(intros w a Hw Hin; destruct Hw as [<-|[]]; unfold L5.in_rng in Hin; cbn [fst snd] in Hin; right; left; lia)) as FR2.
  assert (H2b : getr R2 2%bv = Z_to_bv 64 (sp - 496)) by (rewrite (RP2 2%bv ltac:(ck_in)); exact H2a).
  assert (H4b : getr R2 4%bv = Z_to_bv 64 PML.TP) by (rewrite (RP2 4%bv ltac:(ck_in)); exact H4a).
  assert (H19b : getr R2 19%bv = Z_to_bv 64 (sp - 304)) by (rewrite (RP2 19%bv ltac:(ck_in)); exact H19a).
  assert (H23b : getr R2 23%bv = Z_to_bv 64 (C + 568)) by (rewrite (RP2 23%bv ltac:(ck_in)); exact H23a).
  pose proof (TK.keepsR_trans _ _ _ _ (TK.keepsR_trans _ _ _ _ (sub_ko8 _ _ _ KOR eq_refl) KOa) (ko_rp CCS.KO8 _ _ RP2 eq_refl)) as KOR2.
  assert (Hmo2 : PML.model_ok model2).
  { split; [rewrite (L5C.halted_but_vm _ _ BV2); exact Hh|]. split; [rewrite (L5C.lazy_but_vm _ _ BV2); exact Hl | rewrite (L5C.materialized_but_vm _ _ BV2); exact Hmat]. }
  assert (Hp6 : 0 <= bv_unsigned (getr R 21%bv) < 2 ^ 64) by (pose proof (bv_unsigned_in_range _ (getr R 21%bv)) as X; change (bv_modulus 64) with (2 ^ 64) in X; exact X).
  assert (PF2 : CCS.cells64 M2 (CCS.pframe sp C E (bv_unsigned (getr R 21%bv)) (bv_unsigned (getr R0 23%bv)))).
  { rewrite R23 in PF1. apply (CCS.cells64_x _ M1 M2 _ AG2); [|exact PF1]. intros av Hin. unfold CCS.pframe in Hin. cbn [In] in Hin.
    repeat (destruct Hin as [<-|Hin]; [cbn [fst]; split; [lia | intros i Hi; apply KH2; lia]|]). destruct Hin. }
  refine (cc_rsv LB cr C IS E sp r kx bx rep g R0 M0 model0 K ch p fx2 R2 M2 model2 Hcont Hmo2 (L5C.model_but_vm_trans _ _ _ BV0 BV2) HK0 Hfp2
            H2b H4b H19b H23b KOR2 H2R0 HH2 ISRC2 CHF NLEN LS2 HG CRS STK0 Hrok OC OI OE APCI APCE APIE WF2 CF2 OPT2 RO2 EC2 FR2 _ BOK _
            IOSB2 LOC2 S248b S256b S272b S280b S288b S296b S304b STR2 VZ2 PCL2 DC2 (bv_unsigned (getr R 21%bv)) Hp6 PF2).
  - intros a Ha HO Hd. pose proof (DW a Ha HO Hd) as Hm.
    destruct (not_outside _ _ HO) as (w & Hw & Hin). unfold L5.in_rng in Hin. cbn [In] in Hw.
    apply (L5C.hpres_cdef _ _ _ _ _ _ _ a HP2 Ha); [ | | apply MG1; exact Hm].
    + destruct Hw as [<-|[<-|[<-|[<-|[<-|[<-|[]]]]]]]; cbn [fst snd] in Hin;
        first [right; left; split; lia | right; right; split; [lia | intros Z0; apply (PmLayout.ly_static L LAY) in Z0; lia]].
    + unfold in_errno; rewrite ERR. destruct Hw as [<-|[<-|[<-|[<-|[<-|[<-|[]]]]]]]; cbn [fst snd] in Hin; lia.
  - destruct GU as [(G1 & G2)|G1]; [left; split | right];
      (apply (TK2.u8_x _ M1 M2 AG2); [lia | intros i Hi; unfold TK2.keepH; split; [apply w9_out1; lia | right; right; right; lia] | apply (TK2.u8_x _ M M1 AG1); [lia | intros i Hi; unfold CCS.KE4; lia | assumption]]).
Qed.

Lemma wa_loc_statics_cov : forall K : Z -> Prop, (forall a, 0x10000 <= a < 0xf6c08 -> ~ (0xd675c <= a < 0xd6760) -> K a) -> TK2.statics_cov K.
Proof.
  intros K H. split; [|split].
  - intros a (iv & Hiv & Hr). apply H; unfold PML.ll_foot_csrc in Hiv; repeat (destruct Hiv as [<-|Hiv]; [cbn in Hr; lia|]); destruct Hiv.
  - intros a Ha. unfold PML.IMG_RO_HI in Ha. apply H; lia.
  - intros a Ha. apply H; lia.
Qed.
Lemma cc_loc (LB : list (Z * Z)) (cr : credit) (C IS E sp r kx bx : Z) (rep : PML.srep) (g : PML.ls_state)
  (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K : ShapeAlg.TSet)
  (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model)
