  set (SCR := PMCS.CCTOR_SCR STRTOD_SCR) in *.
  assert (HSCR0 : SCR = 400 + PMCS.RN_SCR STRTOD_SCR /\ 9520 <= PMCS.RN_SCR STRTOD_SCR).
  { unfold SCR, PMCS.CCTOR_SCR, PMCS.CCTOR_MAIN_SCR, PMCS.RN_SCR, PMS.READNEXT_SCR, PMS.PSOME_SCR, PMS.PF_SCR, PMS.CTOR_SCR, PMS.OPNEW_SCR, PML.HEAP_STACK. lia. }
  assert (HOS : PMS.OPNEW_SCR = 8240) by (unfold PMS.OPNEW_SCR, PML.HEAP_STACK; reflexivity).
  assert (HSCR : 432 + PMS.OPNEW_SCR <= SCR) by lia.
