  apply (CCS.s_r_loc FPM fx R M model K sp C IS (IS + 16) Hh Hl Hfp H2 SPOK H8 H18 ltac:(lia) ltac:(lia) OI3 ltac:(lia) ltac:(lia)
           ltac:(unfold box in APCI; exact APCI) NF RO DC I0 J40).
  intros fx1 R1 M1 Hfp1 H2a H1a H10a H9a KS1 C248 C256 C280 C296 AG1 MG1.
  assert (TP1 : getr R1 4%bv = Z_to_bv 64 PML.TP) by (rewrite (KS1 4%bv ltac:(ck_in)); exact H4).
  assert (STKn : L5C.stk (hl_sptop L) M1 (sp - 432) PMS.OPNEW_SCR).
