  assert (KS12 : forall a, 0x10000 <= a < 0xf6c08 -> ~ (0xd675c <= a < 0xd6760) -> CCS.KE3 C a /\ TK2.keepH L LB [] (sp - 432) PMS.OPNEW_SCR a).
  { intros a Ha X. split; [unfold CCS.KE3; lia|]. split; [intros w Hw; destruct Hw | right; right; right; lia]. }
  assert (KB12 : forall q n a, In (q, n) LB -> q <= a < q + n -> CCS.KE3 C a /\ TK2.keepH L LB [] (sp - 432) PMS.OPNEW_SCR a).
