  assert (LOC2 : PML.u64 M2 (C + 40) PML.CLASSIC_IMP) by (apply (TK2.u64_x _ M M2 AG12); [lia | intros i Hi; apply K12; [lia | unfold CCS.KE3; lia] | exact LOC]).
