  assert (S296 : L5.u64_at RSEGS M2 (C + 296) 0) by (apply (TK2.u64_x _ M1 M2 AG2); [lia | intros i Hi; apply KH2; lia | exact C296]).
  assert (SC2 : TK2.statics_cov (fun a => CCS.KE3 C a /\ TK2.keepH L LB [] (sp - 432) PMS.OPNEW_SCR a)) by (apply wa_loc_statics_cov; exact KS12).
  assert (GU2 : (PML.u8 M2 0xd5030 0 /\ PML.u8 M2 0xd5031 0) \/ PML.u8 M2 0xd5030 1).
