  assert (EC2 : PML.ec_at M2 E 0) by (apply (TK2.ec_at_x _ M M2 AG12); [lia | intros i Hi; apply KC; unfold box in APCE; lia | exact EC0]).
  assert (FR1 : TK2.FR L LB sp SCR (fun a => C <= a < C + 656 \/ 0xd5030 <= a < 0xd5032) M0 M1).
  { apply (TK2.FR_grows L LAY LB sp SCR _ M0 M M1 _ FR AG1 MG1 BOK ltac:(lia) ltac:(lia)). intros a Ha. right. left. unfold CCS.KE3 in Ha. lia. }
  assert (FR2 : TK2.FR L LB sp SCR (fun a => C <= a < C + 656 \/ 0xd5030 <= a < 0xd5032) M0 M2).
  { apply (TK2.FR_hpres L LAY LB sp SCR _ M0 M1 M2 LB (sp - 432) PMS.OPNEW_SCR _ FR1 HP2 BOK (incl_refl _)); [lia | lia | lia | lia | lia | lia |].
    intros w a Hw. destruct Hw. }
  assert (DW2 : forall a, 0 <= a < 2 ^ 64 -> ~ L5.outside [(C, 656); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] a ->
            M0 (Z_to_bv 64 a) <> None -> M2 (Z_to_bv 64 a) <> None).
  { intros a Ha HO Hd. apply (L5C.hpres_cdef _ _ _ _ _ _ _ a HP2 Ha); [| | exact (MG1 _ (DW a Ha HO Hd))].
