      destruct Hw as [<-|[<-|[<-|[<-|[<-|[<-|[]]]]]]]; cbn [fst snd] in Hin;
        [right; left; lia | right; left; lia | right; left; lia | right; right; split; [lia | intros Z0; apply (PmLayout.ly_static L LAY) in Z0; lia] ..].
    - destruct (not_outside _ _ HO) as (w & Hw & Hin). unfold L5.in_rng in Hin. unfold in_errno. rewrite ERR.
      destruct Hw as [<-|[<-|[<-|[<-|[<-|[<-|[]]]]]]]; cbn [fst snd] in Hin; lia. }
  assert (KR2 : TK.keepsR [2; 4; 9; 20]%nat R1 R2) by (apply (ko_rp _ _ _ RP2); reflexivity).
  assert (H2b : getr R2 2%bv = Z_to_bv 64 (sp - 432)) by (rewrite (KR2 2%bv ltac:(ck_in)); exact H2a).
  assert (H4b : getr R2 4%bv = Z_to_bv 64 PML.TP) by (rewrite (KR2 4%bv ltac:(ck_in)); exact TP1).
  assert (H9b : getr R2 9%bv = Z_to_bv 64 (C + 8)) by (rewrite (KR2 9%bv ltac:(ck_in)); exact H9a).
  assert (H20b : getr R2 20%bv = Z_to_bv 64 (sp - 304)) by (rewrite (KR2 20%bv ltac:(ck_in)), (KS1 20%bv ltac:(ck_in)); exact H20).
  assert (KOR2 : TK.keepsR CCS.KO7 R0 R2).
  { assert (S73 : forall q, In q CCS.KO7 -> In q CCS.KS3) by (intros q Hq; unfold CCS.KO7, CCS.KS3 in *; cbn [In] in *; intuition).
    apply (TK.keepsR_trans _ _ _ _ KOR). apply (TK.keepsR_trans _ _ _ _ (CK.keepsR_sub _ _ _ _ KS1 S73)).
