  assert (CRS2 : 0 <= kx /\ 0 <= bx /\ 3 * hl_k_per_malloc L + kl * hl_k_per_malloc L + kx <= fst cr /\
                 16384 + 264 + 66 + 3 * hl_b_overhead L + bl + kl * hl_b_overhead L + bx <= snd cr) by (split; [exact CK1|]; split; [exact CK2|]; split; [exact CK3 | exact CK4]).
  apply (cc_new LB cr C IS E sp r kx bx rep g R0 M0 model0 K ch fx2 R2 M2 model2 Hcont (conj Hh2 (conj Hl2 Hmat2)) (L5C.model_but_vm_trans _ _ _ BV0 BV2) HK0 Hfp2
           H2b H4b H9b A0c H20b KOR2 H2R0 HH2 IOSB2 LOC2 S248 S256 S280 S296 ISRC2 GU2 CHF2 NLEN LS2 HG CRS2 STK0 Hrok OC OI OE APCI APCE APIE WF2 CF2 OPT2 SF2 RO2 EC2
           FR2 DW2 BOK DC0).
Qed.

