Lemma cc_init (LB : list (Z * Z)) (cr : credit) (C IS E sp r kx bx : Z) (rep : PML.srep) (g : PML.ls_state)
  (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K : ShapeAlg.TSet)
  (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model)
  (Hcont : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LB' : list (Z * Z)) (cr' : credit) (LBk : list (Z * Z)) (W : list L5.range), PML.fp_ok fx' -> (exists (ch : Z) (ps' : PML.pstate) (code gp' rdst' : Z) (g' : PML.ls_state) (bof' dn' : bool), PMCS.cursor_at M' C IS ch bof' dn' ps' /\ PML.isrc_at M' IS rep gp' rdst' /\ PMCS.rn_bound ps' IS rep gp' (Z.of_nat (length (PML.srep_chars rep))) /\ PML.ec_at M' E code /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.regJ g) /\ PMCUR.wf_c ps' /\ PML.win_ok M' ((ch, 16384) :: LB) ps' /\ PML.u8 M' 0xd5030 1 /\ LB' = PML.ps_blocks ps' ++ (ch, 16384) :: LB /\ LBk = LB /\ PML.pcredit_x L cr' ps' kx bx /\ W = [(C, PMCS.CURSOR_SIZE); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] /\ (code = 0 -> dn' = false -> PML.ps_more ps' = false /\ ((PML.ps_done ps' = true /\ PML.ps_st ps' = PML.ST_DONE) \/ (PMCUR.wf_c (PMCUR.ps_set_more ps' true) /\ PMCS.evc M' (C + 592) 0 ((ch, 16384) :: LB) ps')))) -> regs_preserved R0 R' -> L5C.hpres L LBk sp (PMCS.CCTOR_SCR STRTOD_SCR) W M0 M' -> model_but_vm model0 model' -> hi_heap HI LB' cr' M' (m_vmmaps model') -> srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model') K)
  (Hmo : PML.model_ok model)
  (BV0 : model_but_vm model0 model)
  (HK0 : K [])
  (Hfp : PML.fp_ok fx)
  (H2 : getr R 2%bv = Z_to_bv 64 (sp - 464))
  (H4 : getr R 4%bv = Z_to_bv 64 PML.TP)
  (H8 : getr R 8%bv = Z_to_bv 64 (C + 16))
  (H18 : getr R 18%bv = Z_to_bv 64 IS)
  (H20 : getr R 20%bv = Z_to_bv 64 (sp - 304))
  (KOR : TK.keepsR CCS.KO7 R0 R)
  (H2R0 : getr R0 2%bv = Z_to_bv 64 sp)
  (HH : hi_heap HI LB cr M (m_vmmaps model))
  (IOSB : PML.iosb_at M (C + 96) 0 (C + 32))
  (GLD : PMS.gloc_done M)
  (ISRC : PML.isrc_at M IS rep (PML.srep_data (IS + 80) rep) 0)
  (GU : (PML.u8 M 0xd5030 0 /\ PML.u8 M 0xd5031 0) \/ PML.u8 M 0xd5030 1)
  (CHF0 : forall b0, In b0 (PML.srep_blocks rep) -> In b0 LB)
  (NLEN : Z.of_nat (length (PML.srep_chars rep)) < 2 ^ 26)
  (LSg : PML.ls_ok g M)
  (HG : g <> PML.LS0)
  (CRS : 0 <= kx /\ 0 <= bx /\ 3 * hl_k_per_malloc L + PML.kleft (PMS.ps_init 0 0) * hl_k_per_malloc L + kx <= fst cr /\ 16384 + 264 + 66 + 3 * hl_b_overhead L + PML.bleft (PMS.ps_init 0 0) + PML.kleft (PMS.ps_init 0 0) * hl_b_overhead L + bx <= snd cr)
  (STK0 : L5C.stk (hl_sptop L) M0 sp (PMCS.CCTOR_SCR STRTOD_SCR))
  (Hrok : L5.ra_ok r)
  (OC : PML.obj_on_stack L sp C 656)
  (OI : PML.obj_on_stack L sp IS 272)
  (OE : PML.obj_on_stack L sp E 16)
  (APCI : box (C + 656 <= IS \/ IS + 272 <= C))
  (APCE : box (C + 656 <= E \/ E + 16 <= C))
  (APIE : box (IS + 272 <= E \/ E + 16 <= IS))
  (WF : CCS.cells64 M (CCS.wframe sp r R0))
  (CF : CCS.cells64 M (CCS.cframe sp C IS E (bv_unsigned (getr R0 22%bv))))
  (OPT : CCS.opts_at M (sp - 304))
  (SF : CCS.cells64 M (CCS.sframe sp C E))
  (NF : CCS.cells64 M (CCS.nframe sp C))
  (RO : PML.img_ro M)
  (EC0 : PML.ec_at M E 0)
  (FR : TK2.FR L LB sp (PMCS.CCTOR_SCR STRTOD_SCR) (fun a => C <= a < C + 656 \/ 0xd5030 <= a < 0xd5032) M0 M)
  (DW : forall a, 0 <= a < 2 ^ 64 -> ~ L5.outside [(C, 656); (IS, 272); (E, 16); (0xd4df8, 2); (0xf6848, 544); (0xd5030, 2)] a -> M0 (Z_to_bv 64 a) <> None -> M (Z_to_bv 64 a) <> None)
  (BOK : TK2.blocks_ok L LB)
  (DC0 : L5.defined M0 C 656) :
  srealizes RSEGS SCFG (@PML.cfg fx R CCT.R_INIT M model) K.
Proof.
  pose proof Hmo as (Hh & Hl & Hm).
  pose proof STK0 as (S1 & S2 & S3 & S4 & S5).
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI.
  set (SCR := PMCS.CCTOR_SCR STRTOD_SCR) in *.
  assert (HSCR : SCR = 400 + PMCS.RN_SCR STRTOD_SCR /\ 9520 <= PMCS.RN_SCR STRTOD_SCR).
  { unfold SCR, PMCS.CCTOR_SCR, PMCS.CCTOR_MAIN_SCR, PMCS.RN_SCR, PMS.READNEXT_SCR, PMS.PSOME_SCR, PMS.PF_SCR, PMS.CTOR_SCR, PMS.OPNEW_SCR, PML.HEAP_STACK. lia. }
  destruct HSCR as (HSCR & HRN2).
  assert (SPOK : CK.spok sp) by (split; [lia | exact S1]).
  pose proof OC as (OC1 & OC2 & OC3). pose proof OI as (OI1 & OI2 & OI3). pose proof OE as (OE1 & OE2 & OE3).
  assert (XCI : C + 656 <= IS \/ IS + 272 <= C) by exact APCI.
  assert (XCE : C + 656 <= E \/ E + 16 <= C) by exact APCE.
  assert (XIE : IS + 272 <= E \/ E + 16 <= IS) by exact APIE.
  assert (DC : L5.defined M C 656).
  { intros i Hi. apply DW; [lia | intros HO; apply (HO (C, 656)); [cbn; tauto | unfold L5.in_rng; cbn [fst snd]; lia] | apply DC0; lia]. }
  assert (STKM : L5C.stk (hl_sptop L) M sp SCR) by (split; [exact S1|]; split; [lia|]; split; [lia|]; split; [exact S4|]; intros i Hi; apply (proj2 FR); lia).
  assert (BLK : forall b0, In b0 (PML.srep_blocks rep) -> block_range L (fst b0) (snd b0)) by (intros b0 Hb0; exact (BOK b0 (CHF0 b0 Hb0))).
  apply (CCS.s_r_init FPM fx R M model K sp C Hh Hl Hfp H2 SPOK H8); [lia | exact RO | exact DC |].
  intros fx1 R1 M1 Hfp1 H2_1 H1_1 H10_1 KO1 AG1 MG1.
  assert (SC1 : TK2.statics_cov (CCS.KE2 C)) by (apply TK2.statics_cov_lo; intros a Ha; cc_kt2).
  assert (H4_1 : getr R1 4%bv = Z_to_bv 64 PML.TP) by (rewrite (KO1 4%bv) by (cbn; tauto); exact H4).
  apply (LOCL (C + 40) (sp - 464) CCT.R_LOC fx1 R1 M1 model K Hh Hl HK0 Hfp1).
  - cbv beta.
    split; [apply CK.mk_entry; [exact H1_1 | apply ra_ok_lit; reflexivity | exact H2_1 | exact H4_1 | apply (CK.sub_stk _ M M1 sp SCR); [exact STKM | exact MG1 | apply CK.al16; [exact S1 | reflexivity] | lia | lia | lia]]|].
    split; [exact H10_1|].
    split; [exact (TK2.gloc_done_x _ M M1 AG1 SC1 GLD)|]. split; [exact (TK2.img_ro_x _ M M1 AG1 SC1 RO)|].
    split; [unfold PML.obj_on_stack; split; [lia | split; [lia | apply al8_add; [exact OC3 | reflexivity]]]|].
    apply (L5.defined_grows _ _ _ _ MG1). eapply L5.defined_sub; [exact DC | lia | lia].
  - intros fx2 R2 M2 Hfp2 LOC2 RP2 FB2 MG2. cbv beta in LOC2.
    pose proof (TK2.frame_but_samem _ _ _ FB2) as AG2.
    pose proof (CCTL.samem_tr _ _ _ _ _ AG1 AG2) as AGt.
    pose proof (mem_grows_trans _ _ _ MG1 MG2) as MGt.
    assert (SCt : TK2.statics_cov (fun a => CCS.KE2 C a /\ L5.outside ((sp - 464 - 32, 32) :: [(C + 40, 8)]) a)) by (apply TK2.statics_cov_lo; intros a Ha; cc_kt2).
    assert (KOR2 : TK.keepsR CCS.KO7 R0 R2) by exact (TK.keepsR_trans _ _ _ _ KOR (TK.keepsR_trans _ _ _ _ (CCTL.sub_ko7 CK.CSR _ _ KO1 eq_refl) (ko_rp CCS.KO7 _ _ RP2 eq_refl))).
    assert (H2_2 : getr R2 2%bv = Z_to_bv 64 (sp - 464)) by (rewrite (RP2 2%bv) by (cbn; tauto); exact H2_1).
    assert (H4_2 : getr R2 4%bv = Z_to_bv 64 PML.TP) by (rewrite (RP2 4%bv) by (cbn; tauto); exact H4_1).
    assert (H8_2 : getr R2 8%bv = Z_to_bv 64 (C + 16)) by (rewrite (RP2 8%bv) by (cbn; tauto); rewrite (KO1 8%bv) by (cbn; tauto); exact H8).
    assert (H18_2 : getr R2 18%bv = Z_to_bv 64 IS) by (rewrite (RP2 18%bv) by (cbn; tauto); rewrite (KO1 18%bv) by (cbn; tauto); exact H18).
    assert (H20_2 : getr R2 20%bv = Z_to_bv 64 (sp - 304)) by (rewrite (RP2 20%bv) by (cbn; tauto); rewrite (KO1 20%bv) by (cbn; tauto); exact H20).
    assert (HH2 : hi_heap HI LB cr M2 (m_vmmaps model)).
    { apply (TK2.heap_pure_write L HI HIok LAY _ _ M M2 _ _ HH ltac:(lia) AGt MGt). intros a Ha HK. left. apply not_and_or in HK.
      destruct HK as [HK|HK]; [unfold CCS.KE2 in HK; lia|]. destruct (not_outside _ a HK) as (w & Hw & Hin).
      destruct Hw as [<-|[<-|[]]]; unfold L5.in_rng in Hin; cbn [fst snd] in Hin; lia. }
    assert (IOSB2 : PML.iosb_at M2 (C + 96) 0 (C + 32)).
    { apply (iosb_at_xd _ M M2 _ _ _ AGt); [lia | intros i Hi; cc_kt2 | | exact IOSB].
      apply (L5.defined_grows _ _ _ _ MGt). eapply L5.defined_sub; [exact DC | lia | lia]. }
    assert (ISRC2 : PML.isrc_at M2 IS rep (PML.srep_data (IS + 80) rep) 0).
    { apply (TK2.isrc_at_x _ M M2 AGt); [lia | intros i Hi; cc_kt2 | eapply (CCTL.str_cov_low L); [exact BLK | lia | intros a Ha Hb; cc_kt2 | intros i Hi; cc_kt2] | exact ISRC]. }
    pose proof (TK2.ls_ok_x _ M M2 AGt SCt g LSg) as LSg2.
    pose proof (TK2.img_ro_x _ M M2 AGt SCt RO) as RO2.
    assert (EC02 : PML.ec_at M2 E 0) by (apply (TK2.ec_at_x _ M M2 AGt); [lia | intros i Hi; cc_kt2 | exact EC0]).
    assert (WF2 : CCS.cells64 M2 (CCS.wframe sp r R0)).
    { apply (CCS.cells64_win _ M M2 _ (sp - 56) sp AGt); [lia | lia | intros i Hi; cc_kt2 | | exact WF].
      intros av Hav. unfold CCS.wframe in Hav. repeat (destruct Hav as [<-|Hav]; [cbn [fst]; lia|]). destruct Hav. }
    assert (CF2 : CCS.cells64 M2 (CCS.cframe sp C IS E (bv_unsigned (getr R0 22%bv)))).
    { apply (CCS.cells64_win _ M M2 _ (sp - 368) (sp - 304) AGt); [lia | lia | intros i Hi; cc_kt2 | | exact CF].
      intros av Hav. unfold CCS.cframe in Hav. repeat (destruct Hav as [<-|Hav]; [cbn [fst]; lia|]). destruct Hav. }
    assert (SF2 : CCS.cells64 M2 (CCS.sframe sp C E)).
    { apply (CCS.cells64_win _ M M2 _ (sp - 432) (sp - 400) AGt); [lia | lia | intros i Hi; cc_kt2 | | exact SF].
      intros av Hav. unfold CCS.sframe in Hav. repeat (destruct Hav as [<-|Hav]; [cbn [fst]; lia|]). destruct Hav. }
    assert (NF2 : CCS.cells64 M2 (CCS.nframe sp C)).
    { apply (CCS.cells64_win _ M M2 _ (sp - 456) (sp - 432) AGt); [lia | lia | intros i Hi; cc_kt2 | | exact NF].
      intros av Hav. unfold CCS.nframe in Hav. repeat (destruct Hav as [<-|Hav]; [cbn [fst]; lia|]). destruct Hav. }
    assert (OPT2 : CCS.opts_at M2 (sp - 304)) by (apply (CCS.opts_at_x _ M M2 (sp - 304) AGt); [lia | intros i Hi; cc_kt2 | exact OPT]).
    eapply (cc_loc LB cr C IS E sp r kx bx rep g R0 M0 model0 K fx2 R2 M2 model); try eassumption.
    all: lazymatch goal with
      | |- (_ /\ _) \/ _ => destruct GU as [[U1 U2]|U1]; [left; split | right]; (apply (TK2.u8_x _ M M2 AGt); [lia | intros i Hi; cc_kt2 | assumption])
      | |- TK2.FR _ _ _ _ _ _ _ =>
          eapply TK2.FR_samem; [exact FR | exact AGt | |];
          [ intros a Ha HC HF HE; destruct HC as [(x & Hx & Hr) | [(X1 & X2) | (X1 & X2)]];
            [ destruct (BOK x Hx) as (B0 & B1 & B2 & B3 & B4); cc_kt2 | cc_kt2 | rewrite IHI in X1; cc_kt2 ]
          | intros a _ X; exact (MGt _ X) ]
      | |- forall a, _ => intros a Ha Hin X; apply MGt; exact (DW a Ha Hin X)
      | |- ?G => idtac G
      end.
Qed.

Theorem cursor_ctor_ok : PMCS.cursor_ctor_spec L HI STRTOD_SCR.
Proof.
  unfold PMCS.cursor_ctor_spec, PML.cps_heap.
  intros LB cr C IS E sp r kx bx rep g fx R M model K HH0 Hmo HK0 Hfp PRE Kont.
  destruct PRE as ((H1 & Hra & H2 & H4 & STK) & A0 & A1 & A2 & ISRC & EC0 & RO & GLD & LSg & HG & GU & CHF0 & NLEN & OC & OI & OE & APCI & APCE & APIE & DC & Hkx & Hbx & CRK & CRB).
  unfold PMCS.CURSOR_SIZE in *.
  pose proof Hmo as (Hh & Hl & Hm).
  pose proof STK as (S1 & S2 & S3 & S4 & S5).
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI.
  set (SCR := PMCS.CCTOR_SCR STRTOD_SCR) in *.
  assert (HSCR : SCR = 400 + PMCS.RN_SCR STRTOD_SCR /\ 9520 <= PMCS.RN_SCR STRTOD_SCR).
  { unfold SCR, PMCS.CCTOR_SCR, PMCS.CCTOR_MAIN_SCR, PMCS.RN_SCR, PMS.READNEXT_SCR, PMS.PSOME_SCR, PMS.PF_SCR, PMS.CTOR_SCR, PMS.OPNEW_SCR, PML.HEAP_STACK. lia. }
  destruct HSCR as (HSCR & HRN2).
  assert (SPOK : CK.spok sp) by (split; [lia | exact S1]).
  pose proof OC as (OC1 & OC2 & OC3). pose proof OI as (OI1 & OI2 & OI3). pose proof OE as (OE1 & OE2 & OE3).
  pose proof APCI as XCI. pose proof APCE as XCE. pose proof APIE as XIE. unfold PML.apart in XCI, XCE, XIE.
  pose proof (TK2.blocks_ok_heap L HI HIok _ _ _ _ HH0) as BOK.
  pose proof (conj Hkx (conj Hbx (conj CRK CRB))) as CRS.
  assert (DS : L5.defined M (sp - 512) 512) by (eapply L5.defined_sub; [exact S5 | lia | lia]).
  apply (CCS.s_cc_entry FPM fx R M model K sp C IS E r Hh Hl Hfp H2 SPOK H1 Hra A0 A1 A2); [lia | lia | lia | exact RO | exact DS | exact DC | lia |].
  intros fx1 R1 M1 Hfp1 H2_1 H1_1 H10_1 H11_1 H8_1 H18_1 H19_1 H20_1 WF1 OPT1 CF1 SF1 NF1 VT1 VT2 KO1 AG1 MG1.
  assert (SC1 : TK2.statics_cov (CCS.KE1 sp C)) by (apply TK2.statics_cov_lo; intros a Ha; cc_kt).
  assert (H4_1 : getr R1 4%bv = Z_to_bv 64 PML.TP) by (rewrite (KO1 4%bv) by (cbn; tauto); exact H4).
  apply (INITL (C + 96) (C + 32) (sp - 464) CCT.R_INIT fx1 R1 M1 model K Hh Hl HK0 Hfp1).
  - cbv beta. unfold TPS2.IOSBI_SCR.
    split; [apply CK.mk_entry; [exact H1_1 | apply ra_ok_lit; reflexivity | exact H2_1 | exact H4_1 | apply (CK.sub_stk _ M M1 sp SCR); [exact STK | exact MG1 | apply CK.al16; [exact S1 | reflexivity] | lia | lia | lia]]|].
    split; [exact H10_1|]. split; [exact H11_1|]. split; [lia|].
    split; [exact (TK2.gloc_done_x _ M M1 AG1 SC1 GLD)|]. split; [exact (TK2.img_ro_x _ M M1 AG1 SC1 RO)|].
    split; [unfold PML.obj_on_stack; split; [lia | split; [lia | apply al8_add; [exact OC3 | reflexivity]]]|].
    apply (L5.defined_grows _ _ _ _ MG1). eapply L5.defined_sub; [exact DC | lia | lia].
  - intros fx2 R2 M2 Hfp2 IOSB2 RP2 FB2 MG2. cbv beta in IOSB2. unfold TPS2.IOSBI_SCR in FB2.
    pose proof (TK2.frame_but_samem _ _ _ FB2) as AG2.
    pose proof (CCTL.samem_tr _ _ _ _ _ AG1 AG2) as AGt.
    pose proof (mem_grows_trans _ _ _ MG1 MG2) as MGt.
    assert (SCt : TK2.statics_cov (fun a => CCS.KE1 sp C a /\ L5.outside ((sp - 464 - (16 + 32), 16 + 32) :: [(C + 96, 136)]) a)) by (apply TK2.statics_cov_lo; intros a Ha; cc_kt).
    assert (KOR2 : TK.keepsR CCS.KO7 R R2) by exact (TK.keepsR_trans _ _ _ _ KO1 (ko_rp CCS.KO7 _ _ RP2 eq_refl)).
    assert (H2_2 : getr R2 2%bv = Z_to_bv 64 (sp - 464)) by (rewrite (RP2 2%bv) by (cbn; tauto); exact H2_1).
    assert (H4_2 : getr R2 4%bv = Z_to_bv 64 PML.TP) by (rewrite (RP2 4%bv) by (cbn; tauto); exact H4_1).
    assert (H8_2 : getr R2 8%bv = Z_to_bv 64 (C + 16)) by (rewrite (RP2 8%bv) by (cbn; tauto); exact H8_1).
    assert (H18_2 : getr R2 18%bv = Z_to_bv 64 IS) by (rewrite (RP2 18%bv) by (cbn; tauto); exact H18_1).
    assert (H20_2 : getr R2 20%bv = Z_to_bv 64 (sp - 304)) by (rewrite (RP2 20%bv) by (cbn; tauto); exact H20_1).
    assert (HH2 : hi_heap HI LB cr M2 (m_vmmaps model)).
    { apply (TK2.heap_pure_write L HI HIok LAY _ _ M M2 _ _ HH0 ltac:(lia) AGt MGt). intros a Ha HK. left. apply not_and_or in HK.
      destruct HK as [HK|HK]; [unfold CCS.KE1 in HK; lia|]. destruct (not_outside _ a HK) as (w & Hw & Hin).
      destruct Hw as [<-|[<-|[]]]; unfold L5.in_rng in Hin; cbn [fst snd] in Hin; lia. }
    assert (BLK : forall b0, In b0 (PML.srep_blocks rep) -> block_range L (fst b0) (snd b0)) by (intros b0 Hb0; exact (BOK b0 (CHF0 b0 Hb0))).
    assert (ISRC2 : PML.isrc_at M2 IS rep (PML.srep_data (IS + 80) rep) 0).
    { apply (TK2.isrc_at_x _ M M2 AGt); [lia | intros i Hi; cc_kt | eapply (CCTL.str_cov_low L); [exact BLK | lia | intros a Ha Hb; cc_kt | intros i Hi; cc_kt] | exact ISRC]. }
    pose proof (TK2.ls_ok_x _ M M2 AGt SCt g LSg) as LSg2.
    pose proof (TK2.img_ro_x _ M M2 AGt SCt RO) as RO2.
    pose proof (TK2.gloc_done_x _ M M2 AGt SCt GLD) as GLD2.
    assert (EC02 : PML.ec_at M2 E 0) by (apply (TK2.ec_at_x _ M M2 AGt); [lia | intros i Hi; cc_kt | exact EC0]).
    assert (WF2 : CCS.cells64 M2 (CCS.wframe sp r R)).
    { apply (CCS.cells64_win _ M1 M2 _ (sp - 56) sp AG2); [lia | lia | intros i Hi; cc_kt | | exact WF1].
      intros av Hav. unfold CCS.wframe in Hav. repeat (destruct Hav as [<-|Hav]; [cbn [fst]; lia|]). destruct Hav. }
    assert (CF2 : CCS.cells64 M2 (CCS.cframe sp C IS E (bv_unsigned (getr R 22%bv)))).
    { apply (CCS.cells64_win _ M1 M2 _ (sp - 368) (sp - 304) AG2); [lia | lia | intros i Hi; cc_kt | | exact CF1].
      intros av Hav. unfold CCS.cframe in Hav. repeat (destruct Hav as [<-|Hav]; [cbn [fst]; lia|]). destruct Hav. }
    assert (SF2 : CCS.cells64 M2 (CCS.sframe sp C E)).
    { apply (CCS.cells64_win _ M1 M2 _ (sp - 432) (sp - 400) AG2); [lia | lia | intros i Hi; cc_kt | | exact SF1].
      intros av Hav. unfold CCS.sframe in Hav. repeat (destruct Hav as [<-|Hav]; [cbn [fst]; lia|]). destruct Hav. }
    assert (NF2 : CCS.cells64 M2 (CCS.nframe sp C)).
    { apply (CCS.cells64_win _ M1 M2 _ (sp - 456) (sp - 432) AG2); [lia | lia | intros i Hi; cc_kt | | exact NF1].
      intros av Hav. unfold CCS.nframe in Hav. repeat (destruct Hav as [<-|Hav]; [cbn [fst]; lia|]). destruct Hav. }
    assert (OPT2 : CCS.opts_at M2 (sp - 304)) by (apply (CCS.opts_at_x _ M1 M2 (sp - 304) AG2); [lia | intros i Hi; cc_kt | exact OPT1]).
    eapply (cc_init LB cr C IS E sp r kx bx rep g R M model K fx2 R2 M2 model); try eassumption.
    all: lazymatch goal with
      | |- model_but_vm _ _ => apply L5C.model_but_vm_refl
      | |- box _ => apply boxed; assumption
      | |- (_ /\ _) \/ _ => destruct GU as [[U1 U2]|U1]; [left; split | right]; (apply (TK2.u8_x _ M M2 AGt); [lia | intros i Hi; cc_kt | assumption])
      | |- TK2.FR _ _ _ _ _ _ _ =>
          eapply TK2.FR_samem; [split; [intros; reflexivity | intros a Ha; replace a with (sp - SCR + (a - (sp - SCR))) by lia; apply S5; lia] | exact AGt | |];
          [ intros a Ha HC HF HE; destruct HC as [(x & Hx & Hr) | [(X1 & X2) | (X1 & X2)]];
            [ destruct (BOK x Hx) as (B0 & B1 & B2 & B3 & B4); cc_kt | cc_kt | rewrite IHI in X1; cc_kt ]
          | intros a _ X; exact (MGt _ X) ]
      | |- forall a, _ => intros a Ha Hin X; exact (MGt _ X)
      | |- ?G => idtac G
      end.
Qed.
End H.
